/// <summary>
/// DebuC 22.09.21 Req: 3868 Task: 3870
/// </summary>
/// <param name = "_specialDiscountId">AVASpecialDiscountId</param>
/// <param name = "_forupdate">boolean</param>
/// <returns>AVASpecialDiscount</returns>
static AVASpecialDiscount find(AVASpecialDiscountId  _specialDiscountId, boolean _forupdate = false)
{
    AVASpecialDiscount specialDiscount;

    if(_specialDiscountId)
    {
        specialDiscount.selectForupdate(_forupdate);

        select firstonly specialDiscount
            where specialDiscount.SpecialDiscountId == _specialDiscountId;
    }
    return specialDiscount;
}

/// <summary>
/// DebuC 22.09.21 Req: 3868 Task: 3870
/// </summary>
/// <param name = "_specialDiscountId">AVASpecialDiscountId</param>
/// <param name = "_languageId">LanguageId</param>
/// <returns>FreeTxt</returns>
static FreeTxt txt(AVASpecialDiscountId   _specialDiscountId,
                   LanguageId             _languageId = CompanyInfo::languageId())
{
    AVASpecialDiscount specialDiscount = AVASpecialDiscount::find(_specialDiscountId);
    LanguageTxt      languageTxt = LanguageTxt::find(specialDiscount.TableId,
                                                specialDiscount.RecId,
                                                _languageId);

    if (languageTxt.Txt)
    {
        return languageTxt.Txt;
    }

    if (specialDiscount.SpecialDicountName)
    {
        return specialDiscount.SpecialDicountName;
    }

    return specialDiscount.SpecialDiscountId;
}
